using Microsoft.EntityFrameworkCore;

// Checkout updates Inventory, then Shipments. This job does the reverse.
static async Task CancelAsync(ShopDb db, int orderId, int productId)
{
    await using var tx = await db.Database.BeginTransactionAsync();
    await db.Shipments.Where(s => s.OrderId == orderId).ExecuteUpdateAsync(
        s => s.SetProperty(x => x.Status, "Cancelled"));
    await db.Inventory.Where(i => i.ProductId == productId).ExecuteUpdateAsync(
        s => s.SetProperty(i => i.Reserved, i => i.Reserved - 1));
    await tx.CommitAsync(); // Test: one of the two failed with 1205
}

using Microsoft.EntityFrameworkCore;

// Context registered with UseSqlServer(cs, o => o.EnableRetryOnFailure())
static async Task CancelAsync(ShopDb db, int orderId, int productId)
{
    var strategy = db.Database.CreateExecutionStrategy();
    await strategy.ExecuteAsync(async () =>
    {
        // Same order as checkout: Inventory first, then Shipments
        await using var tx = await db.Database.BeginTransactionAsync();
        await db.Inventory.Where(i => i.ProductId == productId)
            .ExecuteUpdateAsync(s =>
                s.SetProperty(i => i.Reserved, i => i.Reserved - 1));
        await db.Shipments.Where(s => s.OrderId == orderId)
            .ExecuteUpdateAsync(s =>
                s.SetProperty(x => x.Status, "Cancelled"));
        await tx.CommitAsync(); // A rare 1205 reruns this whole block
    });
}
